/**
 * Reporting systems, response criteria and staging systems, from the November 2026 gap census
 * (docs/proposals/gap-census-2026-11.md, types `reporting-systems`, `response-criteria` and `staging-systems`).
 *
 * Each record is a glossary term that says, in plain English, what a category on a report means, and cites the
 * defining publication (DOI resolved on Crossref and its abstract read on Europe PMC on 4 November 2026) or the
 * society's own page, read as raw text. Stage descriptions are read from the National Cancer Institute's PDQ
 * summaries, which reproduce the AJCC tables with permission; the full TNM tables stay in the AJCC and UICC manuals.
 * Where a source said less than a reader would want, the record says only what the source says.
 *
 * Three census findings are fixed here as well: RANO, mRECIST and PCWG3 were aliases of `recist`, iRECIST of
 * `progressive-disease` and PERCIST of the technology `quantitative-imaging-biomarkers`, so a reader searching for
 * any of them landed on a different system. Each now has its own record and the aliases were taken off the old ones.
 */
import type { TermInput } from "@/lib/schema";

const asOf = "2026-11-04";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
const doi = (d: string) => `https://doi.org/${d}`;
type T = Omit<TermInput, "kind" | "asOf"> & { asOf?: TermInput["asOf"] };
const t = (x: T): TermInput => ({ kind: "term", asOf, ...x });

const ACR_RADS = "https://www.acr.org/clinical-resources/clinical-tools-and-reference/reporting-and-data-systems";
const AJCC_2026 = { label: "American College of Surgeons, AJCC Current Staging System 2026 (which chapters are 8th edition and which Version 9)", url: "https://www.facs.org/media/c5ik5tkr/ajcc-current-staging-system-2026.pdf" };
const PDQ = (label: string, url: string) => ({ label: `National Cancer Institute, ${label}`, url });

